#!/usr/bin/env node
/**
 * generate-ds-knowledge.mjs
 *
 * Gera automaticamente o inventário de componentes/composables do skill
 * `dock-ds` a partir do `index.ts` (barrel export) do Design System — a
 * superfície pública REAL e importável. Fecha o gap C.6 do PRD: o skill era
 * mantido à mão, ficava desatualizado, e a IA recriava componentes que já
 * existem.
 *
 * Saídas:
 *   - Atualiza o bloco AUTO-GENERATED em base/skills/dock-ds/SKILL.md
 *   - Escreve base/skills/dock-ds/ds-components-manifest.json (consumo por máquina)
 *
 * Uso:
 *   node scripts/generate-ds-knowledge.mjs --index <caminho/para/index.ts> [--date AAAA-MM-DD]
 *   # default do --index: $DS_INDEX, depois caminhos comuns
 *
 * Pensado para rodar no CI do DS (publica o manifest) e no copilot-config.
 */

import { readFileSync, writeFileSync, existsSync } from 'fs';
import { join, resolve, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const PKG_ROOT = resolve(__dirname, '..'); // copilot-config/
const SKILL_PATH = join(PKG_ROOT, 'base', 'skills', 'dock-ds', 'SKILL.md');
const MANIFEST_PATH = join(PKG_ROOT, 'base', 'skills', 'dock-ds', 'ds-components-manifest.json');

const MARK_START = '<!-- AUTO-GENERATED:components — não editar à mão; rode generate-ds-knowledge.mjs -->';
const MARK_END = '<!-- AUTO-GENERATED:END -->';

function arg(name, fallback) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && process.argv[i + 1] ? process.argv[i + 1] : fallback;
}

function resolveIndexPath() {
  const explicit = arg('index', process.env.DS_INDEX);
  if (explicit) return resolve(explicit);
  const candidates = [
    join(process.cwd(), 'index.ts'),
    join(process.cwd(), 'src', 'design-system', 'index.ts'),
    resolve(PKG_ROOT, '..', '..', 'Design System', 'index.ts'),
  ];
  return candidates.find(existsSync) || null;
}

// Categoriza por palavra-chave no nome do componente.
const CATEGORIES = [
  ['Formulário', /Input|Select|Textarea|Checkbox|Radio|Switch|Slider|OTP|Upload|Form|Combobox|MultiSelect|TagInput|Currency|Number|Phone|CEP|Date|Time|Birthdate|CreditCard|SignaturePad|Rating|SegmentedControl|SecretField|SearchInput|RichTextEditor/],
  ['Ação', /Button|IconButton|Link|Dropdown|MenuItem|ContextMenu|RowActions|BulkActions|CommandPalette|CopyField/],
  ['Layout / Estrutura', /Card|Divider|Stack|Cluster|Grid|Container|SplitPane|AspectRatio|AppShell|Sidebar|Topbar|PageHeader|Drawer|BottomSheet|Show|Hide|Spacer/],
  ['Navegação', /Tabs|Breadcrumb|Pagination|Stepper|Accordion|Menu|TreeView|Timeline|Coachmark/],
  ['Feedback / Estado', /Toast|Alert|Banner|Spinner|Skeleton|Progress|EmptyState|ErrorBoundary|Modal|ConfirmModal|Popover|Tooltip|TermTooltip|NotificationCenter|Countdown/],
  ['Exibição / Dados', /Table|DataGrid|Chart|Sparkline|Heatmap|StatCard|Badge|Chip|Avatar|Tag|Kbd|CodeBlock|DescriptionList|QRCode|LazyImage|CardVisual|ReceiptCard|TransactionCard|InstallmentTable|Calendar|ColumnPicker|Kanban/],
  ['Fintech / RBAC', /Gate|Paywall|RoleBadge|RiskBadge/],
];

function categorize(name) {
  for (const [cat, rx] of CATEGORIES) {
    if (rx.test(name)) return cat;
  }
  return 'Outros';
}

function parseIndex(src) {
  const components = new Set();
  const composables = new Set();
  const types = new Set();

  // export { default as DsXxx } from './components/...'
  const compRx = /export\s*\{\s*default\s+as\s+(Ds[A-Za-z0-9]+)\s*\}\s*from\s*['"]\.\/components\//g;
  let m;
  while ((m = compRx.exec(src)) !== null) components.add(m[1]);

  // export { useX, helperY } from './composables/...'  e  export { ... } from './content|utils|...'
  const namedRx = /export\s*\{([^}]+)\}\s*from\s*['"]\.\/(composables|content|utils)\//g;
  while ((m = namedRx.exec(src)) !== null) {
    for (const raw of m[1].split(',')) {
      const name = raw.trim().replace(/\s+as\s+\w+/, '');
      if (!name || name.startsWith('type ')) continue;
      if (/^use[A-Z]/.test(name) || /^(register|clear|detect)[A-Z]/.test(name)) composables.add(name);
    }
  }

  // export type { A, B } from ...
  const typeRx = /export\s+type\s*\{([^}]+)\}/g;
  while ((m = typeRx.exec(src)) !== null) {
    for (const raw of m[1].split(',')) {
      const name = raw.trim();
      if (name) types.add(name);
    }
  }

  return {
    components: [...components].sort(),
    composables: [...composables].sort(),
    types: [...types].sort(),
  };
}

function buildMarkdown({ components, composables }, date) {
  const byCat = {};
  for (const c of components) {
    const cat = categorize(c);
    if (!byCat[cat]) byCat[cat] = [];
    byCat[cat].push(c);
  }
  const order = ['Formulário', 'Ação', 'Layout / Estrutura', 'Navegação', 'Feedback / Estado', 'Exibição / Dados', 'Fintech / RBAC', 'Outros'];

  let md = `${MARK_START}\n`;
  md += `> Gerado de \`index.ts\` em ${date}. **${components.length} componentes** importáveis.\n`;
  md += `> Para atualizar: \`node scripts/generate-ds-knowledge.mjs --index <DS>/index.ts\`.\n\n`;

  for (const cat of order) {
    const list = byCat[cat];
    if (!list || !list.length) continue;
    md += `### ${cat} (${list.length})\n`;
    md += list.map((c) => `\`${c}\``).join(' · ') + '\n\n';
  }

  if (composables.length) {
    md += `### Composables (${composables.length})\n`;
    md += composables.map((c) => `\`${c}\``).join(' · ') + '\n\n';
  }

  md += `> **Antes de criar qualquer componente, confirme nesta lista se ele já existe.** Importar do pacote > criar local > HTML cru.\n`;
  md += MARK_END;
  return md;
}

function main() {
  const indexPath = resolveIndexPath();
  if (!indexPath || !existsSync(indexPath)) {
    console.error('❌ index.ts do DS não encontrado. Passe --index <caminho> ou defina DS_INDEX.');
    process.exit(1);
  }

  const date = arg('date', new Date(process.env.BUILD_DATE || Date.now()).toISOString().slice(0, 10));
  const src = readFileSync(indexPath, 'utf-8');
  const parsed = parseIndex(src);

  if (parsed.components.length === 0) {
    console.error('❌ Nenhum componente Ds* encontrado em', indexPath);
    process.exit(1);
  }

  // Manifest (machine-readable)
  writeFileSync(
    MANIFEST_PATH,
    JSON.stringify({ generatedAt: date, source: 'index.ts', ...parsed }, null, 2) + '\n'
  );

  // Inject no SKILL.md
  if (!existsSync(SKILL_PATH)) {
    console.error('❌ SKILL.md não encontrado em', SKILL_PATH);
    process.exit(1);
  }
  let skill = readFileSync(SKILL_PATH, 'utf-8');
  const block = buildMarkdown(parsed, date);

  if (skill.includes(MARK_START) && skill.includes(MARK_END)) {
    skill = skill.replace(
      new RegExp(`${MARK_START.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}[\\s\\S]*?${MARK_END.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`),
      block
    );
  } else {
    console.error('❌ Marcadores AUTO-GENERATED não encontrados no SKILL.md. Adicione-os onde a lista deve entrar.');
    process.exit(1);
  }
  writeFileSync(SKILL_PATH, skill);

  console.log(`✅ ${parsed.components.length} componentes, ${parsed.composables.length} composables, ${parsed.types.length} tipos.`);
  console.log(`   SKILL.md atualizado + manifest em ${MANIFEST_PATH.replace(PKG_ROOT, '.')}`);
}

main();
